Elkészítettem a frissített HTML fájlt, amely 100%osan Tiffany Stratton WWE design stílusban lett megtervezve, miközben megőriztem az eredeti oldal alapvető funkcionalitását. Íme a frissített kód:

html
<!DOCTYPE html>
<html lang="hu" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>It's Tiffy Time! 💎</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Poppins:wght@400;500;600;700&display=swap" rel="stylesheet">
    <script src="https://cdnjs.cloudflare.com/ajax/libs/marked/4.0.12/marked.min.js"></script>

    <style>
        /* === TIFFANY STRATTON TÉMA VÁLTOZÓK === */
        :root, .theme-light {
            --bg-primary: #ffe4f5;
            --bg-secondary: #ffffff;
            --bg-tertiary: #ffd1eb;
            --text-primary: #2d1b2e;
            --text-secondary: #8b4789;
            --text-tertiary: #d4a5d0;
            --border-color: rgba(255, 105, 180, 0.3);
            --accent-color: #ff69b4;
            --accent-color-hover: #ff1493;
            --accent-text-color: #ffffff;
            --glass-bg: rgba(255, 255, 255, 0.85);
            --shadow-color: rgba(255, 105, 180, 0.25);
            --input-bg: #fff0f8;
            --gold-accent: #ffd700;
            --sparkle-color: #ffb6d9;
        }

        .theme-dark {
            --bg-primary: #1a0d1f;
            --bg-secondary: #2d1b2e;
            --bg-tertiary: #3d2540;
            --text-primary: #ffe4f5;
            --text-secondary: #d4a5d0;
            --text-tertiary: #8b4789;
            --border-color: rgba(255, 105, 180, 0.4);
            --accent-color: #ff69b4;
            --accent-color-hover: #ff1493;
            --accent-text-color: #ffffff;
            --glass-bg: rgba(45, 27, 46, 0.9);
            --shadow-color: rgba(255, 105, 180, 0.4);
            --input-bg: #3d2540;
            --gold-accent: #ffd700;
            --sparkle-color: #ff69b4;
        }

        /* === ALAPBEÁLLÍTÁSOK === */
        html { -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }
        body {
            font-family: 'Poppins', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            background: linear-gradient(135deg, var(--bg-primary) 0%, #ffd1eb 50%, #ffb6d9 100%);
            color: var(--text-primary);
            transition: background 0.4s ease, color 0.4s ease;
            font-size: 16px;
            overflow: hidden;
            position: relative;
        }

        body::before {
            content: '';
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background-image: 
                radial-gradient(circle at 20% 30%, rgba(255, 215, 0, 0.15) 0%, transparent 50%),
                radial-gradient(circle at 80% 70%, rgba(255, 105, 180, 0.15) 0%, transparent 50%),
                radial-gradient(circle at 50% 50%, rgba(255, 182, 217, 0.1) 0%, transparent 50%);
            pointer-events: none;
            z-index: 0;
        }

        /* === SPARKLE ANIMÁCIÓ === */
        @keyframes sparkle {
            0%, 100% { opacity: 0; transform: scale(0) rotate(0deg); }
            50% { opacity: 1; transform: scale(1) rotate(180deg); }
        }

        .sparkle {
            position: absolute;
            width: 20px;
            height: 20px;
            background: linear-gradient(45deg, var(--gold-accent), var(--sparkle-color));
            clip-path: polygon(50% 0%, 61% 35%, 98% 35%, 68% 57%, 79% 91%, 50% 70%, 21% 91%, 32% 57%, 2% 35%, 39% 35%);
            animation: sparkle 3s infinite;
            pointer-events: none;
        }

        /* === FŐ KOMPONENSEK === */
        .glass-effect { 
            background: var(--glass-bg); 
            backdrop-filter: saturate(180%) blur(20px); 
            -webkit-backdrop-filter: saturate(180%) blur(20px); 
            border: 2px solid var(--border-color); 
            transition: all 0.4s ease;
            box-shadow: 0 8px 32px var(--shadow-color);
        }

        .btn { 
            padding: 12px 28px; 
            border-radius: 50px; 
            font-weight: 700; 
            transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94); 
            border: 2px solid transparent; 
            font-size: 16px;
            text-transform: uppercase;
            letter-spacing: 1px;
            position: relative;
            overflow: hidden;
        }

        .btn::before {
            content: '';
            position: absolute;
            top: 50%;
            left: 50%;
            width: 0;
            height: 0;
            border-radius: 50%;
            background: rgba(255, 255, 255, 0.3);
            transform: translate(-50%, -50%);
            transition: width 0.6s, height 0.6s;
        }

        .btn:hover::before {
            width: 300px;
            height: 300px;
        }

        .btn-primary { 
            background: linear-gradient(135deg, var(--accent-color) 0%, #ff1493 100%);
            color: var(--accent-text-color);
            box-shadow: 0 6px 20px var(--shadow-color);
        }

        .btn-primary:hover { 
            transform: translateY(-3px) scale(1.05); 
            box-shadow: 0 10px 30px var(--shadow-color);
        }

        .btn-secondary { 
            background: var(--bg-secondary); 
            color: var(--accent-color); 
            border: 2px solid var(--accent-color); 
        }

        .btn-secondary:hover { 
            background: var(--accent-color); 
            color: white;
        }

        .input-field { 
            background-color: var(--input-bg); 
            border: 2px solid var(--border-color); 
            border-radius: 20px; 
            padding: 14px 20px; 
            color: var(--text-primary); 
            font-size: 16px; 
            width: 100%; 
            transition: all 0.3s;
            font-weight: 500;
        }

        .input-field:focus-visible { 
            outline: none !important; 
            border-color: var(--accent-color);
            box-shadow: 0 0 0 4px rgba(255, 105, 180, 0.2);
            transform: translateY(-2px);
        }

        /* === ELRENDEZÉS ÉS NÉZETVÁLTÁS === */
        .view { 
            position: absolute; 
            top: 0; 
            left: 0; 
            width: 100%; 
            height: 100%; 
            transition: opacity 0.6s cubic-bezier(0.4, 0, 0.2, 1), transform 0.6s cubic-bezier(0.4, 0, 0.2, 1); 
            z-index: 1;
        }

        .view.hidden { 
            opacity: 0; 
            transform: scale(0.95); 
            pointer-events: none; 
        }

        .fade-in-up { 
            animation: fadeInUp 1s cubic-bezier(0.4, 0, 0.2, 1) forwards; 
            opacity: 0; 
            transform: translateY(20px); 
        }

        @keyframes fadeInUp { 
            to { opacity: 1; transform: translateY(0); } 
        }

        /* === LOGO/TITLE STYLING === */
        .tiffy-title {
            font-family: 'Playfair Display', serif;
            background: linear-gradient(135deg, var(--accent-color) 0%, var(--gold-accent) 50%, var(--accent-color) 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            text-shadow: 0 4px 20px var(--shadow-color);
            position: relative;
            display: inline-block;
        }

        /* === CHAT UI === */
        .chat-bubble { 
            max-width: 80%; 
            padding: 16px 22px; 
            border-radius: 25px; 
            line-height: 1.6;
            font-weight: 500;
        }

        .chat-bubble-user { 
            background: linear-gradient(135deg, var(--accent-color) 0%, #ff1493 100%);
            color: var(--accent-text-color); 
            border-bottom-right-radius: 8px;
            box-shadow: 0 4px 15px var(--shadow-color);
        }

        .chat-bubble-bot { 
            background-color: var(--bg-secondary); 
            border: 2px solid var(--border-color); 
            border-bottom-left-radius: 8px; 
            color: var(--text-primary);
            box-shadow: 0 4px 15px rgba(0,0,0,0.05);
        }

        .prose-custom { 
            color: var(--text-primary); 
            font-size: 15px; 
        }

        .prose-custom a { 
            color: var(--accent-color); 
            font-weight: 600;
        }

        .prose-custom code { 
            background-color: var(--bg-tertiary); 
            padding: 0.2em 0.4em; 
            border-radius: 6px; 
            font-family: monospace; 
        }

        .prose-custom pre { 
            background-color: var(--bg-primary); 
            padding: 1em; 
            border-radius: 12px; 
            border: 2px solid var(--border-color); 
        }

        /* === SCROLLBAR === */
        .custom-scrollbar::-webkit-scrollbar { width: 14px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { 
            background: linear-gradient(180deg, var(--accent-color), var(--gold-accent)); 
            border-radius: 10px; 
            border: 3px solid transparent; 
            background-clip: content-box; 
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { 
            background: var(--accent-color-hover); 
            background-clip: content-box;
        }

        /* === GLOW EFFECT === */
        .glow {
            box-shadow: 0 0 20px var(--accent-color), 0 0 40px var(--accent-color), 0 0 60px var(--accent-color);
        }
    </style>
</head>
<body class="theme-light">
    <!-- Sparkle dekoráció -->
    <div class="sparkle" style="top: 10%; left: 15%; animation-delay: 0s;"></div>
    <div class="sparkle" style="top: 20%; right: 20%; animation-delay: 1s;"></div>
    <div class="sparkle" style="bottom: 15%; left: 25%; animation-delay: 2s;"></div>
    <div class="sparkle" style="top: 60%; right: 10%; animation-delay: 1.5s;"></div>

    <div id="app-container" class="relative w-screen h-screen">

        <!-- KEZDŐOLDAL NÉZET -->
        <section id="view-home" class="view flex flex-col items-center justify-center p-8 text-center custom-scrollbar overflow-y-auto">
            <div class="fade-in-up">
                <h1 class="tiffy-title text-6xl md:text-8xl font-black tracking-tight mb-4">✨ It's Tiffy Time! ✨</h1>
                <p class="mt-8 max-w-3xl text-xl md:text-2xl font-semibold" style="color: var(--text-secondary);">
                    💎 A világ legcsillogóbb platformja! 💎<br>
                    Kérdezz, kutass és alkoss a Buff Barbie stílusával!
                </p>
                <button id="go-to-app-btn" class="btn btn-primary mt-12 text-lg glow">🌟 Platform Indítása 🌟</button>
            </div>
        </section>

        <!-- ALKALMAZÁS NÉZET (3 Oszlopos) -->
        <section id="view-app" class="view hidden flex h-full">
            <aside class="w-64 flex-shrink-0 p-3 flex-col glass-sidebar hidden md:flex glass-effect">
                <div class="flex items-center space-x-3 mb-6 px-2 pt-2">
                    <span class="text-4xl">💎</span>
                    <h1 class="font-black text-xl" style="color: var(--accent-color);">Tiffy Platform</h1>
                </div>
                <div id="session-list" class="flex-1 space-y-2 overflow-y-auto custom-scrollbar"></div>
                <div class="p-2">
                    <a href="#home" id="back-to-home-btn" class="w-full btn btn-secondary text-sm">← Vissza</a>
                </div>
            </aside>

            <main class="flex-1 flex flex-col overflow-hidden" style="background: transparent;">
                <header class="flex-shrink-0 flex items-center justify-between p-5 border-b-2 glass-effect" style="border-color: var(--border-color);">
                    <h2 id="chat-title" class="text-xl font-bold" style="color: var(--accent-color);">💬 Új Beszélgetés</h2>
                    <button id="settings-btn" class="btn btn-secondary !p-3 !rounded-full">
                        <svg class="w-6 h-6" fill="currentColor" viewBox="0 0 20 20">
                            <path d="M5 4a1 1 0 00-2 0v2.268a2 2 0 000 3.464V16a1 1 0 102 0v-6.268a2 2 0 000-3.464V4zM11 4a1 1 0 10-2 0v2.268a2 2 0 000 3.464V16a1 1 0 102 0V9.732a2 2 0 000-3.464V4zM16 3a1 1 0 011 1v2.268a2 2 0 010 3.464V16a1 1 0 11-2 0V9.732a2 2 0 010-3.464V4a1 1 0 011-1z" />
                        </svg>
                    </button>
                </header>
                <div id="chat-messages" class="flex-1 overflow-y-auto p-4 md:p-6 custom-scrollbar">
                    <div id="message-list" class="space-y-5"></div>
                </div>
                <div class="p-4 md:p-6 border-t-2 glass-effect" style="border-color: var(--border-color);">
                    <form id="chat-form" class="relative">
                        <textarea id="chat-input" class="input-field w-full pr-32 resize-none" placeholder="💬 Írj üzenetet vagy kezdj kutatást (!research)..." rows="1"></textarea>
                        <button type="submit" class="absolute right-3 top-1/2 -translate-y-1/2 btn btn-primary">Küldés ✨</button>
                    </form>
                </div>
            </main>

            <aside id="context-panel" class="w-80 flex-shrink-0 p-4 flex-col border-l-2 hidden lg:flex glass-effect" style="border-color: var(--border-color);">
                <h3 class="font-bold px-2 mb-4 text-lg" style="color: var(--accent-color);">📋 Kontextus</h3>
                <div id="context-content" class="flex-1 text-sm custom-scrollbar overflow-y-auto" style="color: var(--text-secondary);"></div>
            </aside>
        </section>
    </div>

    <div id="settings-modal" class="fixed inset-0 z-50 hidden items-center justify-center bg-black/60 backdrop-blur-sm">
        <div class="w-full max-w-md m-4 rounded-3xl shadow-2xl glass-effect">
            <div class="flex items-center justify-between p-6 border-b-2" style="border-color: var(--border-color);">
                <h3 class="text-2xl font-black" style="color: var(--accent-color);">⚙️ Beállítások</h3>
                <button id="close-settings-btn" class="font-bold text-3xl" style="color: var(--accent-color);">&times;</button>
            </div>
            <div class="p-8 space-y-6">
                <div>
                    <label class="block text-sm font-bold mb-3" style="color:var(--text-secondary)">🎨 Téma</label>
                    <button id="theme-toggle" class="w-full btn btn-secondary">Váltás Sötétre 🌙</button>
                </div>
            </div>
        </div>
    </div>

    <template id="message-template">
        <div class="flex">
            <div class="chat-bubble">
                <div class="message-content"></div>
            </div>
        </div>
    </template>

    <template id="loader-template">
        <div class="flex justify-center items-center p-2 space-x-2">
            <div class="w-3 h-3 rounded-full animate-pulse" style="background: linear-gradient(135deg, var(--accent-color), var(--gold-accent));"></div>
            <div class="w-3 h-3 rounded-full animate-pulse" style="background: linear-gradient(135deg, var(--accent-color), var(--gold-accent)); animation-delay: 0.2s;"></div>
            <div class="w-3 h-3 rounded-full animate-pulse" style="background: linear-gradient(135deg, var(--accent-color), var(--gold-accent)); animation-delay: 0.4s;"></div>
        </div>
    </template>

<script>
document.addEventListener('DOMContentLoaded', () => {
    // ===== ÁLLAPOTKEZELÉS =====
    const state = { currentView: 'home', theme: 'light', sessions: {}, activeSessionId: null };

    // ===== DOM ELEMEK =====
    const views = { home: document.getElementById('view-home'), app: document.getElementById('view-app') };
    const goToAppBtn = document.getElementById('go-to-app-btn');
    const backToHomeBtn = document.getElementById('back-to-home-btn');
    const settingsBtn = document.getElementById('settings-btn');
    const closeSettingsBtn = document.getElementById('close-settings-btn');
    const settingsModal = document.getElementById('settings-modal');
    const themeToggleButton = document.getElementById('theme-toggle');
    const chatForm = document.getElementById('chat-form');
    const chatInput = document.getElementById('chat-input');
    const chatTitle = document.getElementById('chat-title');
    const messageList = document.getElementById('message-list');
    const sessionList = document.getElementById('session-list');
    const contextContent = document.getElementById('context-content');

    // ===== NÉZETVÁLTÓ =====
    function switchView(viewName) {
        if (!views[viewName] || state.currentView === viewName) return;
        views[state.currentView].classList.add('hidden');
        views[viewName].classList.remove('hidden');
        state.currentView = viewName;
        if (viewName === 'app' && !state.activeSessionId) { createNewSession('💬 Új Beszélgetés'); }
    }

    // ===== TÉMAVÁLTÓ =====
    function handleThemeToggle() {
        state.theme = state.theme === 'light' ? 'dark' : 'light';
        document.body.className = `theme-${state.theme}`;
        themeToggleButton.textContent = state.theme === 'light' ? 'Váltás Sötétre 🌙' : 'Váltás Világosra ☀️';
    }

    // ===== MUNKAMENET KEZELÉS =====
    function createNewSession(title) {
        const sessionId = `sid_${Date.now()}`;
        state.sessions[sessionId] = { title, messages: [], status: 'active' };
        setActiveSession(sessionId);
        addMessage(sessionId, 'bot', '✨ Üdvözöllek! It\'s Tiffy Time! 💎 Miben segíthetek? Indíts kutatást a `!research` paranccsal, vagy tegyél fel egy kérdést!');
        renderSessionList();
    }

    function setActiveSession(sessionId) {
        state.activeSessionId = sessionId;
        const session = state.sessions[sessionId];
        chatTitle.textContent = session.title;
        messageList.innerHTML = '';
        session.messages.forEach(msg => addMessage(sessionId, msg.sender, msg.content, msg.type, false));
        renderSessionList();
    }

    function renderSessionList() {
        sessionList.innerHTML = '';
        Object.entries(state.sessions).forEach(([id, session]) => {
            const btn = document.createElement('button');
            btn.className = 'w-full text-left px-4 py-3 rounded-2xl font-bold text-sm truncate transition-all';
            btn.style.color = 'var(--text-primary)';
            btn.textContent = session.title;
            if (id === state.activeSessionId) {
                btn.style.background = 'linear-gradient(135deg, var(--accent-color), var(--gold-accent))';
                btn.style.color = 'white';
            }
            btn.onclick = () => setActiveSession(id);
            sessionList.prepend(btn);
        });
    }

    // ===== CHAT FUNKCIÓK =====
    function addMessage(sessionId, sender, content, type = 'html', save = true) {
        if (save) { state.sessions[sessionId].messages.push({ sender, content, type }); }
        if (sessionId !== state.activeSessionId) return;

        const messageTemplate = document.getElementById('message-template');
        const messageEl = messageTemplate.content.cloneNode(true).firstElementChild;
        const bubble = messageEl.querySelector('.chat-bubble');
        const contentDiv = messageEl.querySelector('.message-content');

        messageEl.classList.add(sender === 'user' ? 'justify-end' : 'justify-start', 'fade-in-up');
        bubble.classList.add(sender === 'user' ? 'chat-bubble-user' : 'chat-bubble-bot');

        if (type === 'loading') {
            const loaderTemplate = document.getElementById('loader-template');
            contentDiv.appendChild(loaderTemplate.content.cloneNode(true));
        } else {
            contentDiv.innerHTML = content;
        }

        messageList.appendChild(messageEl);
        messageList.parentElement.scrollTop = messageList.parentElement.scrollHeight;
        return messageEl;
    }

    async function handleChatSubmit(e) {
        e.preventDefault();
        const userInput = chatInput.value.trim();
        if (!userInput || !state.activeSessionId) return;
        const currentSessionId = state.activeSessionId;

        addMessage(currentSessionId, 'user', userInput);
        chatInput.value = '';
        chatInput.style.height = 'auto';

        const { command, query } = parseUserInput(userInput);

        if (command === '!research') {
            state.sessions[currentSessionId].title = '🔍 ' + (query.length > 25 ? query.substring(0, 22) + '...' : query);
            renderSessionList();
            await backendSimulator.research(currentSessionId, query);
        } else {
            const loadingMessage = addMessage(currentSessionId, 'bot', '', 'loading');
            const response = await backendSimulator.chat({ query });
            loadingMessage.remove();
            addMessage(currentSessionId, 'bot', marked.parse(response.reply));
        }
    }

    function parseUserInput(input) {
        const parts = input.split(/\s+/);
        const command = parts[0].toLowerCase();
        if (command === '!research') {
            return { command, query: parts.slice(1).join(' ') };
        }
        return { command: 'chat', query: input };
    }

    // ===== HÁTTÉR SZIMULÁTOR =====
    const backendSimulator = {
        async research(sessionId, query) {
            contextContent.innerHTML = '';
            const updateStatus = (action, progress) => {
                const statusHtml = `<div class="p-3 fade-in-up"><strong style="color: var(--accent-color);">⏳ Folyamatban:</strong><p class="text-sm mt-2">${action}</p><div class="w-full h-3 rounded-full mt-3" style="background-color: var(--bg-tertiary);"><div class="h-3 rounded-full" style="width:${progress}%; background: linear-gradient(90deg, var(--accent-color), var(--gold-accent)); transition: width 0.5s ease;"></div></div></div>`;
                contextContent.innerHTML = statusHtml;
            };

            const sleep = ms => new Promise(res => setTimeout(res, ms));

            updateStatus('✨ Hipotézisek generálása', 10);
            await sleep(1500);
            const hypotheses = Array.from({length: 5}, (_, i) => `💡 Hipotézis ${i+1}: ${query} más szemszögből.`);
            addMessage(sessionId, 'bot', `**✨ Generált hipotézisek:**\n- ${hypotheses.join('\n- ')}`);

            updateStatus('🔍 Párhuzamos forráskeresés', 30);
            await sleep(2000);
            const sources = Array.from({length: 5}, (_, i) => ({
                url: `https://example.com/source/${i+1}`,
                title: `📚 Releváns Forrás ${i+1} a kutatáshoz`,
                text: 'Ez a forrás részletesen tárgyalja a témát, különös tekintettel a legújabb fejleményekre.'
            }));
            addMessage(sessionId, 'bot', `**🎯 Legjobb 5 forrás megtalálva:**\n${sources.map(s => `[${s.title}](${s.url})`).join('\n')}`);

            updateStatus('🧠 Több-modelles szintézis', 70);
            await sleep(2500);

            updateStatus('💎 Kritika és revízió', 90);
            await sleep(1500);

            updateStatus('✅ Jelentés elkészült', 100);
            const report = `# 💎 Kutatási Jelentés\n\n### 📌 Téma: ${query}\n\n✨ Ez egy MI által generált, részletes összefoglaló, amely több forrás és nézőpont szintézisével jött létre.\n\n**🌟 Főbb megállapítások:**\n1. **Első pont:** A kutatás megerősítette, hogy a szimulált adatok alapján a téma relevanciája magas.\n2. **Második pont:** A gazdasági és társadalmi hatások jelentősek lehetnek a következő évtizedben.\n\n*💼 A teljes jelentés letölthető lenne egy valós rendszerben.*`;
            addMessage(sessionId, 'bot', marked.parse(report));
        },
        async chat({ query }) {
            await new Promise(res => setTimeout(res, 800 + Math.random() * 1000));
            return { reply: `💬 A "${query}" kérdésre a válaszom, hogy ez egy komplex téma. ✨ A szimulált tudásbázisom alapján a legfontosabb szempontok a következők... 💎` };
        }
    };

    // ===== ESEMÉNYKEZELŐK =====
    goToAppBtn.addEventListener('click', () => switchView('app'));
    backToHomeBtn.addEventListener('click', (e) => { e.preventDefault(); switchView('home'); });
    settingsBtn.addEventListener('click', () => settingsModal.classList.remove('hidden'));
    closeSettingsBtn.addEventListener('click', () => settingsModal.classList.add('hidden'));
    themeToggleButton.addEventListener('click', handleThemeToggle);
    chatForm.addEventListener('submit', handleChatSubmit);
    chatInput.addEventListener('input', () => { chatInput.style.height = 'auto'; chatInput.style.height = `${Math.min(chatInput.scrollHeight, 200)}px`; });
    chatInput.addEventListener('keydown', (e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); chatForm.requestSubmit(); }});

    // ===== INICIALIZÁLÁS =====
    switchView('home');
});
</script>

